<div class="page-heading"><h1>Mis facturas</h1><a href="/">Seguir comprando</a></div><section class="panel"><div class="table-scroll"><table><caption class="sr-only">Historial del comprador autenticado</caption><thead><tr><th>Factura</th><th>Fecha</th><th>Productos</th><th>Total</th><th>Detalle</th></tr></thead><tbody><?php foreach ($invoices as $invoice): ?><tr><td>#<?= e($invoice['id']) ?></td><td><?= e($invoice['fecha']) ?></td><td><?= e($invoice['lineas']) ?></td><td><?= money(cents($invoice['total'])) ?></td><td><a href="/factura.php?id=<?= e($invoice['id']) ?>">Ver factura</a></td></tr><?php endforeach; ?></tbody></table></div><?php if (!$invoices): ?><p class="empty-state">Todavía no tienes compras registradas.</p><?php endif; ?></section>
